python3 -c "
import json
with open('/app/resources/treasury_bulletin_1988_09.json') as f:
    data = json.load(f)

# Look for any element with page 21 or containing chart data
elements = data.get('document', {}).get('elements', [])
for i, el in enumerate(elements):
    bbox = el.get('bbox', [])
    if bbox and len(bbox) > 0:
        for b in bbox:
            if 'page_id' in b and b['page_id'] == 21:
                print(f'Found element on page 21, type: {el[\"type\"]}')
                if 'content' in el and el['content']:
                    print(f'Content: {str(el[\"content\"])[:3000]}')
                print('---')
"
